package com.security.demo.config; import org.springframework.context.annotation.*; import org.springframework.security.config.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.crypto.bcrypt.*; import org.springframework.security.crypto.password.*; import org.springframework.security.web.*; @Configuration public class SecurityConfig { @Bean SecurityFilterChain filterChain(HttpSecurity http) throws Exception { http.csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("/api/public/**","/api/login").permitAll().requestMatchers("/api/admin/**").hasRole("ADMIN").anyRequest().authenticated()).httpBasic(Customizer.withDefaults()).formLogin(Customizer.withDefaults()); return http.build(); } @Bean PasswordEncoder passwordEncoder(){ return new BCryptPasswordEncoder(); }}